/* CSS PART 1 OF 2 */

/* Design tokens */
:root {
  color-scheme: light;
  --forest: #243d2e;
  --forest-deep: #192e23;
  --sage: #829477;
  --sage-light: #e9eee5;
  --earth: #a47750;
  --cream: #f7f6ef;
  --paper: #fffefa;
  --ink: #263129;
  --muted: #69746b;
  --line: #dce1d7;
  --white: #ffffff;

  --font-heading: Georgia, "Times New Roman", serif;
  --font-body: "Helvetica Neue", Arial, sans-serif;

  --container: 1180px;
  --gutter: clamp(22px, 5vw, 76px);
  --section-space: clamp(76px, 10vw, 132px);
  --radius: 5px;
  --shadow: 0 14px 40px rgba(25, 46, 35, 0.11);
}

/* Reset */
* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 90px;
}

body {
  margin: 0;
  min-width: 320px;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
}

img {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
input,
textarea,
select {
  font: inherit;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

a:focus-visible,
button:focus-visible,
input:focus-visible,
textarea:focus-visible,
select:focus-visible {
  outline: 3px solid #c48c54;
  outline-offset: 4px;
}

::selection {
  color: var(--white);
  background: var(--forest);
}

/* Shared typography */
h1,
h2,
h3,
p {
  margin-top: 0;
}

h1,
h2,
h3 {
  color: var(--forest-deep);
  font-family: var(--font-heading);
  font-weight: 400;
  line-height: 1.12;
  letter-spacing: -0.035em;
}

h1 {
  max-width: 850px;
  margin-bottom: 26px;
  font-size: clamp(3.2rem, 7.6vw, 6.7rem);
}

h2 {
  margin-bottom: 22px;
  font-size: clamp(2.5rem, 5vw, 4.4rem);
}

h3 {
  font-size: clamp(1.45rem, 2.5vw, 2rem);
}

p {
  color: var(--muted);
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 20px;
  color: var(--sage);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.19em;
  line-height: 1.4;
  text-transform: uppercase;
}

.eyebrow::before {
  width: 30px;
  height: 1px;
  background: currentColor;
  content: "";
}

.section-intro {
  max-width: 650px;
  margin-bottom: 48px;
}

.section-intro p {
  max-width: 570px;
  font-size: 1.05rem;
}

.lead {
  font-size: clamp(1.1rem, 1.8vw, 1.3rem);
  line-height: 1.8;
}

.text-link {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  padding-bottom: 5px;
  border-bottom: 1px solid var(--sage);
  color: var(--forest);
  font-weight: 700;
  transition: color 180ms ease, border-color 180ms ease;
}

.text-link:hover {
  border-color: var(--earth);
  color: var(--earth);
}

/* Page layout */
.container {
  width: min(var(--container), calc(100% - var(--gutter) * 2));
  margin-inline: auto;
}

.section {
  padding-block: var(--section-space);
}

.section--cream {
  background: var(--cream);
}

.section--green {
  background: var(--forest);
  color: var(--white);
}

.section--green h2,
.section--green h3 {
  color: var(--white);
}

.section--green p {
  color: rgba(255, 255, 255, 0.78);
}

.section-heading {
  max-width: 720px;
  margin-bottom: 55px;
}

.section-heading--center {
  margin-inline: auto;
  text-align: center;
}

.section-heading--center .eyebrow {
  justify-content: center;
}

/* Header and navigation */
.site-header {
  position: relative;
  z-index: 20;
  background: var(--paper);
  border-bottom: 1px solid rgba(36, 61, 46, 0.09);
}

.header-inner {
  display: flex;
  min-height: 88px;
  align-items: center;
  justify-content: space-between;
  gap: 30px;
}

.brand {
  display: inline-flex;
  min-width: 0;
  align-items: center;
  gap: 13px;
  color: var(--forest);
}

.brand img {
  width: auto;
  max-width: 65px;
  max-height: 62px;
  object-fit: contain;
}

.brand-name {
  display: flex;
  flex-direction: column;
  color: var(--forest);
  font-family: var(--font-heading);
  font-size: 1.35rem;
  line-height: 1.05;
}

.brand-name small {
  margin-top: 5px;
  color: var(--muted);
  font-family: var(--font-body);
  font-size: 0.58rem;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
}

.primary-nav {
  display: flex;
  align-items: center;
  gap: clamp(20px, 3vw, 38px);
}

.primary-nav a:not(.button) {
  color: var(--forest);
  font-size: 0.85rem;
  font-weight: 600;
  transition: color 180ms ease;
}

.primary-nav a:not(.button):hover {
  color: var(--earth);
}

.menu-toggle {
  display: none;
}

/* Buttons */
.button {
  display: inline-flex;
  min-height: 54px;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 14px 25px;
  border: 1px solid transparent;
  border-radius: var(--radius);
  background: var(--forest);
  color: var(--white);
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.07em;
  text-align: center;
  text-transform: uppercase;
  cursor: pointer;
  transition: background 180ms ease, color 180ms ease,
    border-color 180ms ease, transform 180ms ease;
}

.button:hover {
  transform: translateY(-2px);
  background: var(--forest-deep);
}

.button--light {
  border-color: var(--white);
  background: var(--white);
  color: var(--forest);
}

.button--light:hover {
  border-color: var(--white);
  background: transparent;
  color: var(--white);
}

.button--outline {
  border-color: rgba(255, 255, 255, 0.75);
  background: transparent;
  color: var(--white);
}

.button--outline:hover {
  background: var(--white);
  color: var(--forest);
}

.button--earth {
  background: var(--earth);
  color: var(--white);
}

.button--earth:hover {
  background: #875e3d;
}

/* Full-width hero */
.hero {
  position: relative;
  display: flex;
  min-height: min(780px, calc(100svh - 88px));
  align-items: center;
  overflow: hidden;
  background: var(--forest-deep);
  color: var(--white);
  isolation: isolate;
}

.hero-image {
  position: absolute;
  z-index: -2;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 52%;
}

.hero::after {
  position: absolute;
  z-index: -1;
  inset: 0;
  background:
    linear-gradient(
      90deg,
      rgba(18, 37, 26, 0.88) 0%,
      rgba(18, 37, 26, 0.68) 43%,
      rgba(18, 37, 26, 0.17) 100%
    ),
    linear-gradient(
      0deg,
      rgba(18, 37, 26, 0.28),
      transparent 55%
    );
  content: "";
}

.hero-content {
  width: min(var(--container), calc(100% - var(--gutter) * 2));
  margin: 0 auto;
  padding-block: 110px;
}

.hero .eyebrow {
  color: #d1d9c8;
}

.hero h1 {
  color: var(--white);
}

.hero-copy {
  max-width: 570px;
  margin-bottom: 34px;
  color: rgba(255, 255, 255, 0.88);
  font-size: clamp(1.05rem, 1.7vw, 1.2rem);
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  align-items: center;
}

.hero-note {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 38px;
  color: rgba(255, 255, 255, 0.86);
  font-size: 0.78rem;
  font-weight: 600;
  letter-spacing: 0.07em;
}

.hero-note::before {
  width: 34px;
  height: 1px;
  background: #c8d3bd;
  content: "";
}

/* Family-owned introduction */
.intro-section {
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
  align-items: center;
  gap: clamp(45px, 8vw, 110px);
}

.intro-copy {
  max-width: 510px;
}

.intro-copy p {
  margin-bottom: 24px;
}

.intro-visual {
  position: relative;
  min-height: 430px;
  background: var(--sage-light);
}

.intro-visual img {
  width: 100%;
  height: 100%;
  min-height: 430px;
  object-fit: cover;
}

.intro-caption {
  position: absolute;
  right: -20px;
  bottom: 28px;
  max-width: 220px;
  padding: 20px 24px;
  background: var(--paper);
  box-shadow: var(--shadow);
  color: var(--forest);
  font-family: var(--font-heading);
  font-size: 1.2rem;
  line-height: 1.3;
}

/* Services */
.services-section {
  position: relative;
  overflow: hidden;
}

.services-layout {
  display: grid;
  grid-template-columns: 0.8fr 1.2fr;
  align-items: start;
  gap: clamp(45px, 8vw, 100px);
}

.services-intro {
  position: sticky;
  top: 35px;
  max-width: 420px;
}

.services-intro p {
  margin-bottom: 28px;
}

.services-list {
  border-top: 1px solid var(--line);
}

.service-item {
  display: grid;
  grid-template-columns: 65px 1fr;
  gap: 20px;
  padding: 28px 0;
  border-bottom: 1px solid var(--line);
}

.service-number {
  padding-top: 5px;
  color: var(--sage);
  font-family: var(--font-heading);
  font-size: 1.25rem;
}

.service-item h3 {
  margin-bottom: 8px;
}

.service-item p {
  max-width: 540px;
  margin-bottom: 0;
}

/* Local sourcing and care */
.local-care {
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  gap: clamp(40px, 7vw, 90px);
}

.local-care-copy {
  max-width: 530px;
}

.local-care-visual {
  min-height: 400px;
  overflow: hidden;
  background: var(--sage-light);
}

.local-care-visual img {
  width: 100%;
  height: 100%;
  min-height: 400px;
  object-fit: cover;
}

/* Estimate promotion */
.estimate-banner {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 35px;
  padding: clamp(35px, 6vw, 70px);
  overflow: hidden;
  background: var(--forest);
  color: var(--white);
}

.estimate-banner h2 {
  max-width: 650px;
  margin-bottom: 12px;
  color: var(--white);
}

.estimate-banner p {
  max-width: 560px;
  margin-bottom: 0;
  color: rgba(255, 255, 255, 0.8);
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
  }
}
