/* CSS PART 2 OF 2 */

/* Contact and conversion area */
.contact-section {
  padding-block: var(--section-space);
  background: var(--cream);
}

.contact-layout {
  display: grid;
  grid-template-columns: 0.85fr 1.15fr;
  align-items: start;
  gap: clamp(45px, 8vw, 100px);
}

.contact-copy {
  max-width: 440px;
}

.contact-copy h2 {
  margin-bottom: 24px;
}

.contact-copy p {
  margin-bottom: 25px;
}

.contact-details {
  display: grid;
  gap: 13px;
  margin-top: 35px;
}

.contact-detail {
  display: flex;
  align-items: center;
  gap: 13px;
  color: var(--forest);
  font-size: 0.9rem;
  font-weight: 600;
}

.contact-form {
  padding: clamp(25px, 4vw, 48px);
  background: var(--paper);
  box-shadow: var(--shadow);
}

.form-heading {
  margin-bottom: 30px;
}

.form-heading h3 {
  margin-bottom: 8px;
}

.form-heading p {
  margin-bottom: 0;
  font-size: 0.9rem;
}

.form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 21px;
}

.form-field {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 8px;
}

.form-field--full {
  grid-column: 1 / -1;
}

.form-field label {
  color: var(--forest);
  font-size: 0.8rem;
  font-weight: 700;
}

.form-field input,
.form-field select,
.form-field textarea {
  width: 100%;
  min-width: 0;
  min-height: 51px;
  padding: 13px 15px;
  border: 1px solid var(--line);
  border-radius: 3px;
  background: var(--paper);
  color: var(--ink);
  transition: border-color 180ms ease;
}

.form-field textarea {
  min-height: 145px;
  resize: vertical;
}

.form-field input:hover,
.form-field select:hover,
.form-field textarea:hover {
  border-color: var(--sage);
}

.form-field input:focus,
.form-field select:focus,
.form-field textarea:focus {
  border-color: var(--forest);
  outline: 2px solid var(--sage);
  outline-offset: 2px;
}

.form-submit {
  margin-top: 24px;
}

.form-note {
  margin: 14px 0 0;
  font-size: 0.78rem;
  line-height: 1.5;
}

/* Footer */
.site-footer {
  padding: 65px 0 25px;
  background: var(--forest-deep);
  color: var(--white);
}

.footer-main {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 50px;
  padding-bottom: 45px;
}

.footer-brand {
  max-width: 360px;
}

.footer-brand .brand {
  margin-bottom: 20px;
  color: var(--white);
}

.footer-brand .brand-name {
  color: var(--white);
}

.footer-brand .brand-name small {
  color: rgba(255, 255, 255, 0.65);
}

.footer-brand p {
  color: rgba(255, 255, 255, 0.72);
  font-size: 0.9rem;
}

.footer-nav {
  display: flex;
  flex-wrap: wrap;
  gap: 18px 35px;
}

.footer-nav a {
  color: rgba(255, 255, 255, 0.85);
  font-size: 0.85rem;
  transition: color 180ms ease;
}

.footer-nav a:hover {
  color: #d4dfc9;
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  padding-top: 22px;
  border-top: 1px solid rgba(255, 255, 255, 0.18);
  color: rgba(255, 255, 255, 0.62);
  font-size: 0.76rem;
}

/* Responsive navigation and content */
@media (max-width: 900px) {
  :root {
    --section-space: 85px;
  }

  .header-inner {
    min-height: 76px;
  }

  .menu-toggle {
    display: flex;
    width: 44px;
    height: 44px;
    flex: 0 0 44px;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 5px;
    padding: 0;
    border: 1px solid var(--line);
    border-radius: 3px;
    background: transparent;
    color: var(--forest);
    cursor: pointer;
  }

  .menu-toggle span[aria-hidden="true"] {
    display: block;
    width: 20px;
    height: 2px;
    flex: 0 0 2px;
    background-color: currentColor;
  }

  .primary-nav {
    display: none;
    position: absolute;
    top: 100%;
    right: 0;
    left: 0;
    flex-direction: column;
    align-items: stretch;
    gap: 0;
    max-height: calc(100svh - 76px);
    padding: 12px var(--gutter) 22px;
    overflow-y: auto;
    overflow-x: hidden;
    border-top: 1px solid var(--line);
    background: var(--paper);
    box-shadow: var(--shadow);
  }

  .primary-nav.is-open {
    display: flex;
  }

  .primary-nav a {
    display: block;
    width: 100%;
    padding: 13px 0;
    overflow-wrap: anywhere;
  }

  .primary-nav .button {
    margin-top: 10px;
    padding-inline: 18px;
  }

  .intro-section,
  .services-layout,
  .local-care,
  .contact-layout {
    grid-template-columns: 1fr;
  }

  .intro-section,
  .local-care {
    gap: 38px;
  }

  .intro-copy,
  .services-intro,
  .contact-copy {
    max-width: 650px;
  }

  .services-intro {
    position: static;
  }

  .services-layout {
    gap: 40px;
  }

  .intro-visual,
  .intro-visual img {
    min-height: 360px;
  }

  .local-care-visual,
  .local-care-visual img {
    min-height: 350px;
  }

  .contact-layout {
    gap: 45px;
  }

  .estimate-banner {
    align-items: flex-start;
    flex-direction: column;
  }

  .footer-main {
    flex-direction: column;
    gap: 35px;
  }
}

@media (max-width: 600px) {
  :root {
    --gutter: 22px;
    --section-space: 70px;
  }

  body {
    font-size: 15px;
  }

  h1 {
    font-size: clamp(3rem, 13vw, 4.5rem);
  }

  h2 {
    font-size: clamp(2.4rem, 10vw, 3.3rem);
  }

  .brand {
    gap: 9px;
  }

  .brand img {
    max-width: 48px;
    max-height: 49px;
  }

  .brand-name {
    font-size: 1.12rem;
  }

  .brand-name small {
    font-size: 0.52rem;
  }

  .hero {
    min-height: 690px;
    min-height: min(760px, calc(100svh - 76px));
  }

  .hero-image {
    object-position: 60% center;
  }

  .hero::after {
    background:
      linear-gradient(
        90deg,
        rgba(18, 37, 26, 0.82),
        rgba(18, 37, 26, 0.48)
      ),
      linear-gradient(
        0deg,
        rgba(18, 37, 26, 0.5),
        transparent 85%
      );
  }

  .hero-content {
    padding-block: 85px;
  }

  .hero-copy {
    font-size: 1rem;
  }

  .hero-actions {
    align-items: stretch;
    flex-direction: column;
  }

  .hero-actions .button {
    width: 100%;
  }

  .hero-note {
    margin-top: 27px;
    font-size: 0.7rem;
  }

  .section-intro {
    margin-bottom: 35px;
  }

  .section-heading {
    margin-bottom: 38px;
  }

  .intro-visual,
  .intro-visual img {
    min-height: 280px;
  }

  .intro-caption {
    right: 12px;
    bottom: 12px;
    max-width: 190px;
    padding: 14px 17px;
    font-size: 1rem;
  }

  .service-item {
    grid-template-columns: 38px minmax(0, 1fr);
    gap: 12px;
    padding-block: 23px;
  }

  .service-item h3 {
    font-size: 1.45rem;
  }

  .local-care-visual,
  .local-care-visual img {
    min-height: 270px;
  }

  .estimate-banner {
    padding: 30px 23px;
  }

  .estimate-banner .button {
    width: 100%;
  }

  .contact-form {
    padding: 25px 19px;
  }

  .form-grid {
    grid-template-columns: minmax(0, 1fr);
    gap: 17px;
  }

  .form-field--full {
    grid-column: auto;
  }

  .form-submit,
  .form-submit .button {
    width: 100%;
  }

  .footer-nav {
    flex-direction: column;
    gap: 12px;
  }

  .footer-bottom {
    flex-direction: column;
    gap: 8px;
  }
}

/* Visible keyboard focus */
:focus-visible {
  outline: 3px solid #bd8650;
  outline-offset: 4px;
}

.site-footer a:focus-visible,
.section--green a:focus-visible {
  outline-color: #e5c39e;
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}
